-- 0065_sample_cars_back.sql
-- The owner's request of October 19, 2026: "Add the sample cars back for a moment, the website looks rough without them.
-- And assign sample photos to cars uploaded without photos." (docs/changes/2026-10-19-sample-cars-back.md)
--   1. The 20 sample cars of the original seed (web/scripts/seed.mjs, prototype/tools/src/data.mjs) as a catalogue in the
--      database. "Show sample cars" (Admin > Cars > Sample cars, and Admin > Settings > Site) recreates the missing ones
--      with their photos, rates and listings, restores the retired ones and publishes them; "Hide sample cars" takes
--      every sample car off the site in one click, never refused (no booking, request or enquiry is in the way). Sample
--      cars stay vehicles.is_sample: noindex and out of the sitemap (0035, 0061). Shown once by this migration.
--   2. A request on a sample car is an enquiry, never a booking: public.submit_booking_request sends it to
--      app.sample_car_enquiry (a lead, kind sample_car, reference EQ-1001, and a customer service task "Suggest a
--      similar real car"), and no booking can be created on a sample car (a guard on bookings). The live chat's facts
--      mark the sample cars, so the assistant offers a similar real car.
--   3. Why a real car is not on the site: app.vehicle_public_gates lists what is left (onboarding steps, rates,
--      details, plate check, the listing review, bookings off), each with its one action; Admin > Cars shows it and the
--      verify workflow prints it. Sample photos for a car without photos (0054) are unchanged: every public surface reads
--      app.public_listing_photos / public_listing_row.

-- ================================================================ 1. the catalogue
create table sample_car_catalogue (
  slug        text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  sort_order  integer not null,
  data        jsonb not null check (jsonb_typeof(data) = 'object'),
  updated_at  timestamptz not null default now()
);
comment on table sample_car_catalogue is 'The 20 sample cars of the original seed (0065): what "Show sample cars" recreates. Generated by supabase/seed/sample_cars_gen.mjs.';
alter table sample_car_catalogue enable row level security;
create policy admin_all on sample_car_catalogue for all to authenticated using (app.is_admin()) with check (app.is_admin());
revoke all on sample_car_catalogue from anon, authenticated;
grant select on sample_car_catalogue to authenticated;
grant all on sample_car_catalogue to service_role;
create trigger audit_sample_car_catalogue after insert or update or delete on sample_car_catalogue for each row execute function app.audit_row();

