-- SAMPLE CARS END

-- ================================================================ 2. show and hide
-- The sample owner, agreement and renter of the seed (found by their addresses, created when missing), their addresses
-- suppressed so nothing is ever emailed to them.
create or replace function app.sample_owner() returns uuid
language plpgsql security definer set search_path = public, app as $$
declare
  v_user uuid;
  v_owner uuid;
begin
  select o.id into v_owner from owners o where lower(o.email) = 'sample.owner@example.test' order by o.created_at limit 1;
  if v_owner is null then
    select id into v_user from users where lower(email) = 'sample.owner@example.test';
    if v_user is null then
      insert into users (email, full_name) values ('sample.owner@example.test', 'Sample Owner') returning id into v_user;
    end if;
    insert into user_roles (user_id, role) values (v_user, 'owner') on conflict do nothing;
    insert into owners (user_id, owner_type, legal_name, status, email, phone)
    values (v_user, 'individual', 'Sample Owner', 'active', 'sample.owner@example.test', '416-555-0100') returning id into v_owner;
  end if;
  if not exists (select 1 from owner_agreements a where a.owner_id = v_owner and a.kind = 'enrollment') then
    insert into owner_agreements (owner_id, kind, agreement_number, agreement_date, status)
    values (v_owner, 'enrollment', 'EA-SAMPLE', '2026-08-15', 'signed');
  end if;
  insert into email_suppressions (email, scope, reason, detail)
  select e, 'all', 'manual', 'sample data address (0065)' from unnest(array['sample.owner@example.test', 'sample.renter@example.test']) e
   where not exists (select 1 from email_suppressions s where s.email = e and s.lifted_at is null);
  return v_owner;
end $$;

-- One catalogue car: added when missing (vehicle, signed schedule, fee terms, classes, rates, young driver fees, listing,
-- photos as static files of the site: no file in the photo bucket), restored and published when it is there. Returns 'added', 'shown' or 'kept'.
create or replace function app.sample_car_show_one(p_slug text, p_by uuid) returns text
language plpgsql security definer set search_path = public, app as $$
declare
  c jsonb;
  v_owner uuid;
  v_agreement uuid;
  v uuid;
  v_sched uuid;
  k text;
  ph jsonb;
  j integer := 0;
begin
  select data into c from sample_car_catalogue where slug = p_slug;
  if c is null then raise exception 'Unknown sample car %', p_slug using errcode = 'P0002'; end if;
  select l.vehicle_id into v from vehicle_listings l join vehicles x on x.id = l.vehicle_id where l.slug = p_slug and x.is_sample;
  if v is null then
    select x.id into v from vehicles x where x.is_sample and upper(x.vin) = c ->> 'vin';
  end if;
  if v is not null then
    update vehicles set retired_at = null, retired_by = null, retired_reason = null, bookings_enabled = true,
           status = case when status in ('available', 'on_rent', 'cleaning') then status else 'available' end
     where id = v and (retired_at is not null or not bookings_enabled or status not in ('available', 'on_rent', 'cleaning'));
    if not exists (select 1 from vehicle_listings l where l.vehicle_id = v) then
      insert into vehicle_listings (vehicle_id, slug, headline, description, features, seats, transmission, status, published_at, first_published_at,
                                    body_style, drivetrain, doors, luggage, specs, home_area, is_featured, channels)
      values (v, p_slug, c ->> 'headline', c ->> 'blurb', array(select jsonb_array_elements_text(c -> 'features')), (c ->> 'seats')::smallint,
              c ->> 'transmission', 'published', now(), now(), c ->> 'body', c ->> 'drive', (c ->> 'doors')::smallint, c ->> 'bags',
              jsonb_build_object('consumption', c ->> 'consumption', 'luggage_bags', (c ->> 'bags')::integer), c ->> 'area', (c ->> 'featured')::boolean, array['website']);
      return 'shown';
    end if;
    update vehicle_listings set status = 'published', published_at = now(), first_published_at = coalesce(first_published_at, now()),
           unpublished_at = null, unpublished_reason = null
     where vehicle_id = v and status <> 'published';
    if found then return 'shown'; end if;
    return 'kept';
  end if;

  v_owner := app.sample_owner();
  select id into v_agreement from owner_agreements where owner_id = v_owner and kind = 'enrollment' order by created_at limit 1;
  insert into vehicles (owner_id, fleet_number, year, make, model, trim, colour, fuel, vin, plate, class, status, management_mode, onboarding_method,
                        on_fleet_policy, fleet_policy_added_on, enrollment_date, body_type, owner_pickup_address, is_sample)
  values (v_owner, case when exists (select 1 from vehicles x where x.fleet_number = c ->> 'fleet_number') then null else c ->> 'fleet_number' end,
          (c ->> 'year')::smallint, c ->> 'make', c ->> 'model', c ->> 'trim', c ->> 'colour', (c ->> 'fuel')::fuel_type, c ->> 'vin',
          case when exists (select 1 from vehicles x where x.plate = c ->> 'plate') then null else c ->> 'plate' end,
          (c ->> 'class')::vehicle_class, 'available', 'managed', 'transfer', true, '2026-09-01', '2026-09-01', c ->> 'body',
          case when (c ->> 'owner_pickup')::boolean then 'Sample owner address, Toronto, ON' end, true)
  returning id into v;
  insert into vehicle_schedules (vehicle_id, owner_agreement_id, schedule_number, vehicle_number, held_by, title_status, management_mode, onboarding_method,
                                 insurance_fee_cents, tracker_fee_cents, install_fee_cents, revenue_share_bps, enrollment_date, signed_at)
  values (v, v_agreement, 'VS-SAMPLE-' || p_slug, (select sort_order from sample_car_catalogue where slug = p_slug), 'individual', 'owned_outright', 'managed', 'transfer',
          45000, 2500, 10000, 3500, '2026-09-01', now())
  returning id into v_sched;
  insert into vehicle_fee_history (vehicle_id, vehicle_schedule_id, source, insurance_fee_cents, tracker_fee_cents, revenue_share_bps, effective_from)
  values (v, v_sched, 'signed_schedule', 45000, 2500, 3500, '2026-09-01');
  for k in select jsonb_array_elements_text(c -> 'classes') loop
    insert into vehicle_class_links (vehicle_id, class_code) select v, k where exists (select 1 from vehicle_classes vc where vc.code = k) on conflict do nothing;
  end loop;
  insert into rate_cards (vehicle_id, daily_rate_cents, weekend_rate_cents, weekly_rate_cents, monthly_rate_cents, km_allowance_per_day, overage_cents_per_km,
                          deposit_cents, delivery_fee_cents, pickup_fee_cents, effective_from)
  values (v, (c #>> '{rates,daily}')::bigint, (c #>> '{rates,weekend}')::bigint, (c #>> '{rates,weekly}')::bigint, (c #>> '{rates,monthly}')::bigint,
          (c ->> 'km_per_day')::integer, (c ->> 'overage')::bigint, (c ->> 'deposit')::bigint, (c ->> 'delivery')::bigint, (c ->> 'delivery')::bigint, '2026-09-01');
  if jsonb_typeof(c -> 'young') = 'object' then
    insert into vehicle_fee_overrides (vehicle_id, fee_type_code, amount_cents, effective_from)
    values (v, 'young_driver_18_20', (c #>> '{young,a}')::bigint, '2026-09-01'), (v, 'young_driver_21_25', (c #>> '{young,b}')::bigint, '2026-09-01');
  end if;
  insert into vehicle_listings (vehicle_id, slug, headline, description, features, seats, transmission, status, published_at, first_published_at,
                                body_style, drivetrain, doors, luggage, specs, home_area, is_featured, channels)
  values (v, p_slug, c ->> 'headline', c ->> 'blurb', array(select jsonb_array_elements_text(c -> 'features')), (c ->> 'seats')::smallint,
          c ->> 'transmission', 'published', now(), now(), c ->> 'body', c ->> 'drive', (c ->> 'doors')::smallint, c ->> 'bags',
          jsonb_build_object('consumption', c ->> 'consumption', 'luggage_bags', (c ->> 'bags')::integer), c ->> 'area', (c ->> 'featured')::boolean, array['website']);
  for ph in select * from jsonb_array_elements(c -> 'photos') loop
    insert into vehicle_photos (vehicle_id, angle, shot_type, original_path, processed_path, status, sort_order, is_cover, alt_text, width, height,
                                variants, background_status, is_public, approved_at)
    values (v, ph ->> 'shot', ph ->> 'shot', 'original' || (ph ->> 'path'), ph ->> 'path', 'approved', j, j = 0, ph ->> 'alt', (ph ->> 'width')::integer,
            (ph ->> 'height')::integer, '[]'::jsonb, 'done', true, now());
    j := j + 1;
  end loop;
  return 'added';
end $$;

-- Show: every catalogue car on the site. p_by null is this migration (or the deploy); otherwise an Admin.
create or replace function app.sample_cars_show(p_by uuid) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare
  r record;
  v_res text;
  v_added integer := 0;
  v_shown integer := 0;
begin
  if p_by is not null then perform app.assert_admin(p_by); end if;
  for r in select slug from sample_car_catalogue order by sort_order loop
    v_res := app.sample_car_show_one(r.slug, p_by);
    if v_res = 'added' then v_added := v_added + 1; elsif v_res = 'shown' then v_shown := v_shown + 1; end if;
  end loop;
  insert into audit_log (actor_user_id, action, entity_table, entity_id, after)
  values (p_by, 'sample_cars_show', 'vehicles', 'sample_cars', jsonb_build_object('added', v_added, 'shown', v_shown));
  return jsonb_build_object('added', v_added, 'shown', v_shown, 'state', app.sample_cars_state());
end $$;

-- Hide: every sample car off the site at once. Never refused: nothing (a request, an enquiry, a booking) is in the way.
create or replace function app.sample_cars_hide(p_by uuid) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare
  n integer;
begin
  if p_by is not null then perform app.assert_admin(p_by); end if;
  update vehicle_listings l set status = 'unpublished', unpublished_at = now(), unpublished_reason = 'Sample cars hidden'
    from vehicles v where v.id = l.vehicle_id and v.is_sample and l.status in ('published', 'paused');
  get diagnostics n = row_count;
  insert into audit_log (actor_user_id, action, entity_table, entity_id, after)
  values (p_by, 'sample_cars_hide', 'vehicles', 'sample_cars', jsonb_build_object('hidden', n));
  return jsonb_build_object('hidden', n, 'state', app.sample_cars_state());
end $$;

-- How many sample cars there are and how many are on the site (the button says Show or Hide from this).
create or replace function app.sample_cars_state() returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_build_object(
    'catalogue', (select count(*) from sample_car_catalogue),
    'cars', (select count(*) from vehicles v where v.is_sample),
    'public', (select count(*) from vehicle_listings l join vehicles v on v.id = l.vehicle_id where v.is_sample and l.status in ('published', 'paused')),
    'enquiries', (select count(*) from leads where kind = 'sample_car'),
    'open_enquiries', (select count(*) from leads where kind = 'sample_car' and status = 'new'))
$$;

-- ================================================================ 3. a request on a sample car is an enquiry
-- The local stack's sample cars (web/scripts/seed.mjs without --production) keep taking real bookings: the end-to-end
-- tests book them. Everywhere else a sample car is never booked.
alter table vehicles add column sample_bookable boolean not null default false;
comment on column vehicles.sample_bookable is
  'A sample car that takes real bookings: only the local stack''s seed sets it, for the end-to-end tests (0065). Otherwise a request on a sample car is an enquiry and no booking is created on it.';
alter table leads drop constraint if exists leads_kind_check;
alter table leads add constraint leads_kind_check check (kind in ('owner_program', 'contact', 'insurer', 'launch_notice', 'other', 'chat', 'sample_car'));
create sequence sample_enquiry_seq start 1001;

insert into task_rules (task_type, queue, title, priority, due_kind, due_amount, description) values
  ('sample_car_enquiry', 'cs', 'Suggest a similar real car', 'high', 'opening_minutes', 5,
   'A visitor asked for an example car (a sample car, not a real one): suggest a similar real car with a quote, by phone or email')
on conflict (task_type) do update set queue = excluded.queue, title = excluded.title, priority = excluded.priority,
  due_kind = excluded.due_kind, due_amount = excluded.due_amount, description = excluded.description;

create or replace function app.sample_car_enquiry(p_request jsonb, p_ip inet default null, p_user_agent text default null, p_user uuid default null) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare
  v vehicles;
  r jsonb := coalesce(p_request -> 'renter', '{}'::jsonb);
  v_email text := lower(nullif(btrim(r ->> 'email'), ''));
  v_phone text := nullif(btrim(r ->> 'mobile'), '');
  v_name text := nullif(left(btrim(r ->> 'full_name'), 120), '');
  v_key text := nullif(p_request ->> 'request_key', '');
  v_lead leads;
  v_ref text;
  v_pick timestamptz := nullif(p_request ->> 'pickup_at', '')::timestamptz;
  v_ret timestamptz := nullif(p_request ->> 'return_at', '')::timestamptz;
  v_when text;
  v_mkt boolean := coalesce((p_request #>> '{consents,marketing,opted_in}')::boolean, false);
begin
  select * into v from vehicles where id = nullif(p_request ->> 'vehicle_id', '')::uuid;
  if v.id is null or not v.is_sample then raise exception 'Not a sample car' using errcode = '22023'; end if;
  if v_email is null and v_phone is null then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Give an email address or a phone number.');
  end if;
  -- the same request sent twice (the browser's idempotency key) is one enquiry
  if v_key is not null then
    select * into v_lead from leads where kind = 'sample_car' and payload ->> 'request_key' = v_key;
    if v_lead.id is not null then
      return jsonb_build_object('ok', true, 'enquiry', true, 'created', false, 'booking_number', v_lead.payload ->> 'reference', 'lead_id', v_lead.id);
    end if;
  end if;
  v_ref := 'EQ-' || nextval('sample_enquiry_seq');
  v_when := case when v_pick is not null and v_ret is not null
                 then app.fmt_day(app.local_date(v_pick)) || ' to ' || app.fmt_day(app.local_date(v_ret)) end;
  insert into leads (kind, name, email, phone, message, payload, source, consent_marketing, consent_text, consent_at)
  values ('sample_car', v_name, v_email, v_phone, left(p_request ->> 'note', 1000),
          jsonb_strip_nulls(jsonb_build_object('reference', v_ref, 'request_key', v_key, 'vehicle_id', v.id, 'car', app.vehicle_name(v.id),
            'slug', (select slug from vehicle_listings where vehicle_id = v.id), 'class', v.class, 'body_type', v.body_type,
            'pickup_at', v_pick, 'return_at', v_ret, 'dates', v_when, 'pickup_place', p_request ->> 'pickup_place', 'return_place', p_request ->> 'return_place',
            'request', p_request - 'consents', 'user_id', p_user, 'user_agent', left(p_user_agent, 300))),
          'web', v_mkt, case when v_mkt then p_request #>> '{consents,marketing,text}' end, case when v_mkt then now() end)
  returning * into v_lead;
  perform app.raise_task(p_type => 'sample_car_enquiry', p_due_at => app.task_due('first_reply', null), p_queue => 'cs',
    p_title => left(format('Suggest a similar real car: %s asked for the %s (an example car)%s', coalesce(v_name, v_email, v_phone), app.vehicle_name(v.id),
                           coalesce(', ' || v_when, '')), 200),
    p_detail => format('Enquiry %s. Contact: %s. The %s is an example car on the site, not a real one: suggest a similar real car (same kind of car and price) with a quote, or call back.%s',
                       v_ref, concat_ws(', ', v_email, v_phone), app.vehicle_name(v.id), coalesce(' Note: ' || left(p_request ->> 'note', 300), '')),
    p_vehicle => v.id, p_related_table => 'leads', p_related_id => v_lead.id, p_dedupe => 'sample-enquiry:' || v_lead.id);
  return jsonb_build_object('ok', true, 'enquiry', true, 'created', true, 'booking_number', v_ref, 'lead_id', v_lead.id);
end $$;

-- The public request: a sample car becomes an enquiry; every other car goes on as before.
create or replace function public.submit_booking_request(p_request jsonb, p_ip inet default null, p_user_agent text default null, p_user uuid default null)
returns jsonb language plpgsql set search_path = public, app as $$
begin
  if exists (select 1 from vehicles v where v.id = nullif(p_request ->> 'vehicle_id', '')::uuid and v.is_sample and not v.sample_bookable) then
    return app.sample_car_enquiry(p_request, p_ip, p_user_agent, p_user);
  end if;
  return app.submit_booking_request(p_request, p_ip, p_user_agent, p_user);
end $$;

-- No booking on a sample car, from anywhere (a request, Add a rental, a quote turned into an offer). The local seed's
-- sample calendar (request id 'seed') and its bookable sample cars are the only exceptions.
create or replace function app.bookings_no_sample_car() returns trigger
language plpgsql security definer set search_path = public, app as $$
begin
  if exists (select 1 from vehicles v where v.id = new.vehicle_id and v.is_sample and not v.sample_bookable)
     and coalesce(current_setting('app.request_id', true), '') <> 'seed' then
    raise exception 'This is an example car (a sample car), not a real one: it cannot be booked. Choose a real car' using errcode = '23514';
  end if;
  return new;
end $$;
create trigger bookings_no_sample_car before insert or update of vehicle_id on bookings
  for each row execute function app.bookings_no_sample_car();

-- The live chat's facts: each car says whether it is an example car.
alter function app.server_chat_facts() rename to server_chat_facts_0060;
create or replace function app.server_chat_facts() returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_set(f, '{fleet}', coalesce((select jsonb_agg(c || jsonb_build_object('sample', coalesce(v.is_sample and not v.sample_bookable, false)) order by n)
                                             from jsonb_array_elements(f -> 'fleet') with ordinality x(c, n)
                                             left join vehicles v on v.id = nullif(c ->> 'vehicle_id', '')::uuid), '[]'::jsonb))
    from (select app.server_chat_facts_0060() as f) s
$$;

-- ================================================================ 4. why a real car is not on the site
-- What is left before a car is on the site, in order, each with its one action and who it waits on. Empty: on the site.
create or replace function app.vehicle_public_gates(p_vehicle uuid) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare
  v vehicles;
  l vehicle_listings;
  ob vehicle_onboardings;
  g jsonb := '[]'::jsonb;
  c record;
  v_problems text[];
  v_open text[];
begin
  select * into v from vehicles where id = p_vehicle;
  if v.id is null then return jsonb_build_array(jsonb_build_object('code', 'missing', 'label', 'Car not found', 'action', 'None', 'who', 'carmacars')); end if;
  if v.retired_at is not null then
    return jsonb_build_array(jsonb_build_object('code', 'retired', 'label', 'Retired', 'action', 'Restore the car (Admin > Cars > the car > Retire or delete)', 'who', 'carmacars'));
  end if;
  if v.status in ('exited', 'total_loss', 'declined') then
    return jsonb_build_array(jsonb_build_object('code', 'closed', 'label', 'Left the program (' || v.status || ')', 'action', 'None: the car is no longer in the program', 'who', 'carmacars'));
  end if;
  if v.management_mode = 'turo_only' then
    return jsonb_build_array(jsonb_build_object('code', 'turo_only', 'label', 'Turo only', 'action', 'None: a Turo-only car is not listed on the website', 'who', 'carmacars'));
  end if;
  if exists (select 1 from public_vehicle_listings p where p.vehicle_id = v.id) then return '[]'::jsonb; end if;
  select * into l from vehicle_listings where vehicle_id = v.id;
  -- onboarding: each open step of the checklist except the photos and the listing (sample photos stand in; the listing is below)
  if v.status = 'onboarding' then
    select * into ob from vehicle_onboardings where vehicle_id = v.id;
    if ob.id is null then
      g := g || jsonb_build_object('code', 'onboarding', 'label', 'Onboarding not started', 'action', 'Start the onboarding (Admin > Owners and partners > Applications: approve the car)', 'who', 'carmacars');
    else
      for c in select * from app.onboarding_checklist(v.id) x where x.status = 'open' and x.code not in ('photos', 'listing') order by x.sort_order loop
        g := g || jsonb_build_object('code', c.code, 'label', c.label, 'action', c.next_action, 'who', c.waits_on);
      end loop;
      if jsonb_array_length(g) = 0 then
        g := g || jsonb_build_object('code', 'enrollment', 'label', 'Enrollment not confirmed',
                                     'action', 'Confirm the enrollment (the insurer''s written confirmation that the car is on the fleet policy): the car becomes ready to list', 'who', 'carmacars');
      end if;
    end if;
  elsif v.status not in ('ready_to_list', 'available', 'on_rent', 'cleaning') then
    g := g || jsonb_build_object('code', 'status', 'label', 'Out of service (' || v.status || ')', 'action', 'Put the car back in service', 'who', 'carmacars');
  end if;
  if not exists (select 1 from rate_cards rc where rc.vehicle_id = v.id and rc.effective_from <= now() and (rc.effective_to is null or rc.effective_to > now())) then
    g := g || jsonb_build_object('code', 'rates', 'label', 'No rates', 'action', 'Set the rates (Admin > Cars > the car > Rates)', 'who', 'carmacars');
  end if;
  v_problems := app.listing_spec_problems(v.id);
  if (app.settings()).listing_plate_check_required and not app.vehicle_uses_sample_photos(v.id) then
    select array_agg(coalesce(st.label, ph.shot_type) order by st.seq, ph.sort_order) into v_open
      from vehicle_photos ph join listing_shot_types st on st.code = ph.shot_type
     where ph.vehicle_id = v.id and ph.replaced_at is null and ph.status = 'approved' and ph.is_public and st.is_public
       and ph.processed_path is not null and ph.plate_status = 'unchecked';
    if cardinality(v_open) > 0 then
      g := g || jsonb_build_object('code', 'plates', 'label', 'Plate check', 'action', 'Cover the plate or mark it not visible: ' || array_to_string(v_open, ', '), 'who', 'carmacars');
    end if;
  end if;
  if l.id is null or l.status not in ('published', 'paused') then
    g := g || jsonb_build_object('code', 'listing', 'label', case when l.publish_at > now() then 'Listing scheduled' else 'Listing not published' end,
                                 'action', case when l.publish_at > now() then 'Nothing: it publishes on ' || app.fmt_day(app.local_date(l.publish_at))
                                                else 'Review and publish the listing (Admin > Cars > Listings)'
                                                     || case when cardinality(v_problems) > 0 then ', filling in ' || lower(array_to_string(v_problems, ', ')) else '' end
                                                     || case when app.vehicle_uses_sample_photos(v.id) then '; it shows sample photos until real photos are approved' else '' end end,
                                 'who', 'carmacars');
  elsif l.status = 'paused' then
    g := g || jsonb_build_object('code', 'paused', 'label', 'Listing paused', 'action', 'Resume the listing', 'who', 'carmacars');
  end if;
  if not v.bookings_enabled then
    g := g || jsonb_build_object('code', 'bookings_off', 'label', 'Bookings turned off', 'action', 'Turn bookings on for the car', 'who', 'carmacars');
  end if;
  if v.management_mode = 'self_managed' and v.in_arrears then
    g := g || jsonb_build_object('code', 'arrears', 'label', 'Owner in arrears', 'action', 'Collect the overdue owner invoice', 'who', 'owner');
  end if;
  return g;
end $$;

-- Every real car that is not on the site, with what is left (Admin > Cars, and the verify workflow's notices).
create or replace function app.cars_not_public() returns jsonb
language sql stable security definer set search_path = public, app as $$
  select coalesce(jsonb_agg(jsonb_build_object('vehicle_id', x.id, 'name', app.vehicle_name(x.id), 'status', x.status, 'gates', x.gates,
                                               'next', x.gates -> 0 ->> 'action', 'sample_photos', app.vehicle_uses_sample_photos(x.id))
                            order by x.created_at), '[]'::jsonb)
    from (select v.*, app.vehicle_public_gates(v.id) as gates from vehicles v
           where not v.is_sample and v.retired_at is null and v.status not in ('exited', 'total_loss', 'declined')
             and v.management_mode <> 'turo_only'
             and not exists (select 1 from public_vehicle_listings p where p.vehicle_id = v.id)) x
$$;

-- ================================================================ 5. the doors and privileges
create or replace function app.ops65(p_user uuid, p_call text, p_name text, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
begin
  if p_call = 'ops_read' then
    perform app.assert_admin(p_user);
    if p_name = 'sample_cars_state' then return app.sample_cars_state(); end if;
    if p_name = 'cars_not_public' then return app.cars_not_public(); end if;
    raise exception 'Unknown read %', p_name using errcode = '22023';
  end if;
  if p_name = 'sample_cars_show' then return app.sample_cars_show(p_user); end if;
  if p_name = 'sample_cars_hide' then return app.sample_cars_hide(p_user); end if;
  raise exception 'Unknown action %', p_name using errcode = '22023';
end $$;

alter function app.door(uuid, text, text, text, jsonb) rename to door_pre0065;
create or replace function app.door(p_user uuid, p_aal text, p_call text, p_name text, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
begin
  if (p_call = 'ops_read' and p_name in ('sample_cars_state', 'cars_not_public'))
     or (p_call in ('ops_do', 'admin_do') and p_name in ('sample_cars_show', 'sample_cars_hide')) then
    perform app.door_begin(p_user, p_aal);
    return app.ops65(p_user, p_call, p_name, coalesce(p, '{}'::jsonb) - '_va');
  end if;
  return app.door_pre0065(p_user, p_aal, p_call, p_name, p);
end $$;

do $$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'app' and p.proname = any (array['sample_owner', 'sample_car_show_one', 'sample_cars_show', 'sample_cars_hide', 'sample_cars_state',
              'sample_car_enquiry', 'bookings_no_sample_car', 'server_chat_facts', 'vehicle_public_gates', 'cars_not_public', 'ops65', 'door'])
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    execute format('grant execute on function %s to service_role', f.sig);
  end loop;
end $$;
revoke all on function public.submit_booking_request(jsonb, inet, text, uuid) from public, anon, authenticated;
grant execute on function public.submit_booking_request(jsonb, inet, text, uuid) to service_role;

-- Each renamed function keeps its privileges; the function in its place gets the same.
do $$
declare
  r record;
  v_new regprocedure;
  g text;
begin
  for r in select p.oid, m.new_name, oidvectortypes(p.proargtypes) as args
             from pg_proc p join pg_namespace n on n.oid = p.pronamespace
             join (values ('door_pre0065', 'door'), ('server_chat_facts_0060', 'server_chat_facts')) m(old_name, new_name) on m.old_name = p.proname
            where n.nspname = 'app' loop
    v_new := format('app.%I(%s)', r.new_name, r.args)::regprocedure;
    execute format('revoke all on function %s from public, anon, authenticated', v_new);
    foreach g in array array['anon', 'authenticated', 'service_role'] loop
      if has_function_privilege(g, r.oid, 'execute') then execute format('grant execute on function %s to %I', v_new, g); end if;
    end loop;
  end loop;
end $$;

