-- (the test suite, a new local stack before its seed) gets none here.
do $$
begin
  if exists (select 1 from vehicles where is_sample)
     or exists (select 1 from audit_log where action = 'vehicle_delete' and before ->> 'is_sample' = 'true') then
    perform app.sample_cars_show(null);
  end if;
end $$;

